```solidity: MagicAnimalCarousel.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract MagicAnimalCarousel {
    error AnimalNameTooLong();

    uint256 public constant MAX_CAPACITY = 256;

    uint256 private constant OWNER_MASK = 0x000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF;
    uint256 private constant ANIMAL_MASK = 0x000000FFFFFFFFFFFFFFFFFFFF00000000000000000000000000000000000000000000;
    uint256 private constant NEXT_ID_MASK = 0xFFFFFFFFFFFFFFFFFFFFFFFF00000000000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF;

    mapping(uint256 => uint256) public carousel;
    uint256 public currentCrateId;

    constructor() {
        carousel[0] ^= (1 << 160);
    }

    function setAnimalAndSpin(string calldata animal) external {
        uint256 encodedAnimal = encodeAnimalName(animal);
        uint256 nextCrateId = carousel[currentCrateId] & NEXT_ID_MASK;

        uint256 current = carousel[currentCrateId];
        current = (current & ~ANIMAL_MASK) | (encodedAnimal << 160);
        current = (current & ~NEXT_ID_MASK) | ((nextCrateId + 1) % MAX_CAPACITY);
        current = (current & ~OWNER_MASK) | uint256(uint160(msg.sender));

        carousel[currentCrateId] = current;
        currentCrateId = (nextCrateId + 1) % MAX_CAPACITY;
    }

    function changeAnimal(string calldata animal, uint256 crateId) external {
        uint256 owner = carousel[crateId] & OWNER_MASK;
        if (owner != 0) {
            require(msg.sender == address(uint160(owner)), "Not crate owner");
        }

        uint256 encodedAnimal = encodeAnimalName(animal);

        if (encodedAnimal != 0) {
            uint256 current = carousel[crateId];
            current = (current & ~ANIMAL_MASK) | (encodedAnimal << 160);
            current = (current & NEXT_ID_MASK) | uint256(uint160(msg.sender));
            carousel[crateId] = current;
        } else {
            uint256 current = carousel[crateId];
            current = current & ~OWNER_MASK;
            carousel[crateId] = current;
        }
    }

    function encodeAnimalName(string calldata animalName) public pure returns (uint256) {
        if (bytes(animalName).length > 12) {
            revert AnimalNameTooLong();
        }

        bytes32 packed = bytes32(abi.encodePacked(animalName));
        uint256 encoded = uint256(packed) >> 160;
        return encoded;
    }
}
```

